@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500;1,600&display=swap');
:root{--bg:#101510;--panel:#171d17;--panel2:#1b221b;--line:#2b342c;--text:#e9ecdf;--muted:#899083;--dim:#626b60;--lime:#c0d786;--lime2:#95ad5d;--gold:#e5b56a;--red:#d77e6e;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--serif:'Playfair Display',Georgia,serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh;background-image:radial-gradient(ellipse at 74% -18%,rgba(128,148,91,.09),transparent 40%),radial-gradient(ellipse at -12% 48%,rgba(111,126,77,.05),transparent 35%)}button,input{font:inherit}.app-shell{max-width:1440px;margin:auto;padding:0 62px}.topbar{height:74px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--text);font-size:15px;letter-spacing:2.6px;font-weight:700}.brand-mark{color:var(--lime);font-size:23px}.brand-light{font-weight:400;color:#aab1a2}.top-center,.save-state,.section-label,.small-label,.map-footer,.sort-label,.input-hint,.turn-foot,footer,.eyebrow,.coordinates{font:10px var(--mono);letter-spacing:1.15px}.top-center{display:flex;align-items:center;gap:11px;color:#a6ac9c}.live-dot,.save-state i,.turn-indicator i{width:7px;height:7px;border-radius:50%;background:var(--lime);display:inline-block;box-shadow:0 0 10px #bed78655}.top-divider{color:#4b5548}.header-actions{display:flex;align-items:center;gap:15px}.save-state{color:var(--dim);font-size:9px;display:flex;align-items:center;gap:7px}.save-state i{width:5px;height:5px}.icon-button{width:31px;height:31px;background:none;border:1px solid var(--line);color:#909989;border-radius:50%;font-size:16px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--lime2);color:var(--lime);transform:rotate(20deg)}main{padding-top:42px}.hero-row{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:31px}.eyebrow{color:var(--lime);font-size:9px;display:flex;align-items:center;gap:10px}.eyebrow-line{height:1px;width:23px;background:var(--lime)}h1{font:500 43px/1.12 var(--serif);letter-spacing:-.7px;margin:12px 0 0}h1 em{color:var(--lime);font-weight:500}.hero-note{display:flex;align-items:flex-start;gap:12px;margin:0 4px 5px 0;color:#969d8e}.hero-note p{font-size:12px;line-height:1.7;margin:0}.note-star{font-size:16px;color:var(--gold)}.overview-grid{display:grid;grid-template-columns:1.45fr 1fr;gap:16px}.panel{background:linear-gradient(145deg,rgba(26,33,26,.97),rgba(22,28,22,.98));border:1px solid var(--line);border-radius:5px}.world-panel,.status-panel{min-height:286px}.panel-head{padding:21px 23px 15px;display:flex;align-items:flex-start;justify-content:space-between}.section-label{color:var(--lime2);font-size:9px;letter-spacing:1.35px}.panel-title{font:500 19px var(--serif);margin-top:5px;letter-spacing:.1px}.map-key{display:flex;gap:15px;padding-top:5px;color:#858d7f;font:9px var(--mono)}.map-key span{display:flex;align-items:center;gap:6px}.key-dot{width:6px;height:6px;border-radius:50%;display:inline-block}.key-dot.people{background:var(--lime)}.key-dot.frontier{border:1px dashed #9a8055}.world-map{height:162px;margin:0 22px;position:relative;overflow:hidden;border:1px solid #29342a;border-radius:3px;background-color:#131b17;background-image:linear-gradient(rgba(172,187,144,.045) 1px,transparent 1px),linear-gradient(90deg,rgba(172,187,144,.045) 1px,transparent 1px),radial-gradient(ellipse at 35% 45%,#34463a 0%,#23342d 27%,transparent 28%),radial-gradient(ellipse at 74% 60%,#344439 0%,#26372f 21%,transparent 22%),radial-gradient(ellipse at 52% 22%,#303f34 0%,#23332c 15%,transparent 16%),radial-gradient(ellipse at 12% 77%,#293a31 0%,#202e28 11%,transparent 12%);background-size:27px 27px,27px 27px,100% 100%,100% 100%,100% 100%,100% 100%;}.world-map:before,.world-map:after{content:"";position:absolute;border:1px solid rgba(186,201,156,.11);border-radius:50%;width:320px;height:140px;transform:rotate(-17deg);left:8%;top:9%}.world-map:after{width:220px;height:100px;left:45%;top:33%;transform:rotate(23deg)}.map-river{position:absolute;width:44%;height:65%;left:28%;top:13%;border-right:1px solid #8da78a3b;border-radius:50%;transform:rotate(24deg)}.map-label{position:absolute;color:#80907b;font:8px var(--mono);letter-spacing:1.3px;opacity:.72;text-transform:uppercase;white-space:nowrap}.map-settlement{position:absolute;z-index:2;display:flex;align-items:center;gap:6px;transform:translate(-50%,-50%);white-space:nowrap}.map-settlement i{width:8px;height:8px;background:var(--lime);border-radius:50%;border:2px solid #253027;box-shadow:0 0 0 3px #bed7862b,0 0 14px #bed786aa}.map-settlement small{font:8px var(--mono);color:#d7dfca;text-shadow:0 2px 4px #000}.map-settlement.new i{background:var(--gold);box-shadow:0 0 0 3px #e5b56a35,0 0 14px #e5b56a99}.map-footer{height:39px;margin:0 22px;display:flex;align-items:center;justify-content:space-between;color:#899184;font-size:9px}.map-footer b{color:#cbd2bf;font-weight:500}.muted-separator{color:#455044}.coordinates{color:#667161;font-size:8px}.status-icon{color:var(--lime);font-size:22px}.era-block{padding:4px 23px 0}.small-label{display:block;color:#828a7d;font-size:8px;letter-spacing:1.2px}.era-name{font:500 25px var(--serif);margin:7px 0 13px}.era-progress{height:3px;background:#30392e;width:100%;overflow:hidden}.era-progress-bar{height:100%;background:linear-gradient(90deg,var(--lime2),var(--lime));width:0;transition:width .5s ease}.progress-caption{display:flex;justify-content:space-between;font:9px var(--mono);color:#7d8676;margin-top:8px}.progress-caption span:last-child{color:var(--lime)}.metric-row{display:grid;grid-template-columns:repeat(3,1fr);margin:22px 23px 0;border-top:1px solid var(--line);padding-top:14px}.metric{display:flex;flex-direction:column;gap:2px;border-right:1px solid var(--line);padding-left:12px}.metric:first-child{padding-left:0}.metric:last-child{border:0}.metric strong{font:500 22px var(--serif);color:#e2e8d8;margin-top:4px}.metric-caption{font-size:9px;color:#778071}.divine-favor{display:flex;align-items:center;gap:11px;margin:15px 23px 0;padding-top:11px;border-top:1px solid var(--line)}.favor-icon{color:var(--gold);font-size:17px}.divine-favor p{font-size:10px;color:#969d8c;margin:4px 0 0}.favor-value{font:13px var(--mono);color:var(--gold);margin-left:auto}.lower-grid{display:grid;grid-template-columns:1.45fr 1fr;gap:16px;margin-top:16px;align-items:start}.left-column{display:flex;flex-direction:column;gap:16px}.civ-panel{min-height:181px}.title-count{font:10px var(--mono);color:#798171;vertical-align:middle;margin-left:4px}.sort-label{color:#697264;font-size:8px;padding-top:5px}.sort-label span{font-size:13px;margin-left:4px}.civilizations{padding:0 23px 13px}.civ-row{display:grid;grid-template-columns:minmax(135px,1.3fr) .83fr .85fr .82fr;align-items:center;gap:12px;border-top:1px solid #2a332a;padding:13px 0}.civ-identity{display:flex;align-items:center;gap:10px;min-width:0}.civ-emblem{width:29px;height:29px;border:1px solid #45523c;color:var(--lime);border-radius:50%;display:grid;place-items:center;font:14px var(--serif);flex-shrink:0;background:#222d23}.civ-row:nth-child(2) .civ-emblem{color:var(--gold);border-color:#5d4c32;background:#2c281e}.civ-name{font-size:11px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.civ-sub{font:8px var(--mono);color:#737d70;margin-top:3px}.civ-stat .small-label{font-size:7px}.civ-stat strong{display:block;font:11px var(--mono);color:#c9d0c0;margin-top:6px}.focus-chip{border:1px solid #394233;border-radius:2px;padding:4px 6px;font:8px var(--mono);color:#b4c28e;display:inline-block}.focus-chip.war{color:#e69c82;border-color:#594035}.opinion{display:flex;align-items:center;gap:6px}.opinion-dot{width:6px;height:6px;border-radius:50%;background:var(--lime)}.opinion-dot.angry{background:var(--red)}.opinion-dot.neutral{background:var(--gold)}.empty-civ{padding:17px 0;color:#747d70;font-size:11px}.chronicle-panel{min-height:190px}.chronicle-head{padding-bottom:10px}.chronicle-count{font:9px var(--mono);color:#77816f;border:1px solid #343d33;padding:5px 7px}.chronicle{padding:0 23px 14px;max-height:200px;overflow:auto;scrollbar-color:#48513f transparent;scrollbar-width:thin}.event{display:grid;grid-template-columns:42px 12px 1fr;gap:8px;padding:8px 0;border-top:1px solid #293229;align-items:start}.event-time{font:8px var(--mono);color:#747e6d;padding-top:2px}.event-mark{width:6px;height:6px;border-radius:50%;background:var(--lime2);margin-top:4px;box-shadow:0 0 8px #c0d78633}.event:first-child .event-mark{background:var(--gold)}.event-copy{font-size:10px;line-height:1.55;color:#a6ad9e}.event-copy strong{font-weight:600;color:#d4dacb}.action-panel{padding-bottom:0}.action-panel>.panel-head{padding-bottom:9px}.power-glyph{font-size:20px;color:var(--gold)}.action-intro{margin:0 23px 15px;color:#909889;font-size:10px;line-height:1.6}.action-list{display:flex;flex-direction:column;gap:7px;padding:0 23px}.action-card{width:100%;background:#1b231c;border:1px solid #303a2e;color:var(--text);display:grid;grid-template-columns:31px 1fr auto;align-items:center;text-align:left;gap:10px;padding:10px 11px;cursor:pointer;border-radius:3px;transition:background .18s,border .18s,transform .18s}.action-card:hover{background:#242e23;border-color:#697b4d;transform:translateY(-1px)}.action-card:active{transform:translateY(0)}.action-card:disabled{opacity:.42;cursor:not-allowed;transform:none}.action-icon{width:29px;height:29px;display:grid;place-items:center;border:1px solid #3c4937;border-radius:50%;font-size:14px;color:var(--lime);background:#212b20}.action-card:nth-child(2) .action-icon{color:#dbac68;border-color:#594932;background:#2d281e}.action-card:nth-child(3) .action-icon{color:#9baed0;border-color:#3e4a5b;background:#202733}.action-copy strong{display:block;font-size:10px;font-weight:600}.action-copy small{display:block;color:#828b7d;font-size:9px;margin-top:3px;line-height:1.35}.action-cost{font:8px var(--mono);color:#929a8b;white-space:nowrap}.action-cost span{color:var(--gold)}.custom-form{border-top:1px solid var(--line);margin:16px 23px 0;padding-top:14px}.custom-form label{margin-bottom:8px}.input-wrap{height:38px;display:flex;border:1px solid #394337;background:#121812;border-radius:3px}.input-wrap:focus-within{border-color:#778b54;box-shadow:0 0 0 2px #9fb77317}.input-wrap input{min-width:0;flex:1;background:transparent;border:0;outline:0;color:var(--text);font-size:10px;padding:0 11px}.input-wrap input::placeholder{color:#657060}.input-wrap button{width:37px;border:0;background:transparent;color:var(--lime);font-size:18px;cursor:pointer}.input-hint{font-size:8px;color:#687264;letter-spacing:.2px;margin-top:7px}.turn-foot{border-top:1px solid var(--line);margin-top:15px;padding:12px 23px;display:flex;justify-content:space-between;color:#666f62;font-size:8px}.turn-indicator{color:#aab39e;display:flex;gap:7px;align-items:center}.turn-indicator i{width:5px;height:5px}footer{height:62px;display:flex;align-items:center;justify-content:space-between;color:#626c5f;font-size:8px;letter-spacing:1.15px}footer i{font-style:normal;color:var(--lime2);padding:0 4px}.toast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,20px);padding:11px 16px;border:1px solid #536243;background:#1a2319;color:#d9e3cb;border-radius:3px;font-size:11px;box-shadow:0 10px 35px #0008;opacity:0;pointer-events:none;transition:.25s;z-index:8}.toast.show{opacity:1;transform:translate(-50%,0)}.modal-backdrop{position:fixed;inset:0;background:#080b08d9;display:grid;place-items:center;padding:20px;z-index:10}.modal-backdrop[hidden]{display:none}.modal{width:min(420px,100%);background:#1a211a;border:1px solid #394336;border-radius:5px;padding:26px}.modal h2{font:500 29px var(--serif);margin:10px 0}.modal p{font-size:12px;line-height:1.6;color:#929b8d}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:25px}.quiet-button,.danger-button{border:1px solid #414b3d;background:none;color:#b9c1b2;border-radius:3px;padding:9px 12px;font-size:10px;cursor:pointer}.danger-button{background:#c0d786;color:#192016;border-color:#c0d786;font-weight:700}.danger-button span{margin-left:7px}.visually-hidden{position:absolute!important;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
@media(max-width:900px){.app-shell{padding:0 28px}.overview-grid,.lower-grid{grid-template-columns:1fr 1fr}.civ-row{grid-template-columns:minmax(115px,1.2fr) .7fr .75fr .7fr;gap:7px}.sort-label{display:none}.world-panel,.status-panel{min-height:300px}.world-map{height:160px}}
@media(max-width:680px){.app-shell{padding:0 17px}.topbar{height:61px}.top-center{font-size:8px;gap:7px}.save-state{display:none}.header-actions{gap:8px}.icon-button{width:29px;height:29px}.brand{font-size:13px}.hero-row{padding-top:2px;margin-bottom:22px}main{padding-top:29px}h1{font-size:37px}.hero-note{display:none}.overview-grid,.lower-grid{grid-template-columns:1fr;gap:12px}.world-panel{min-height:278px}.status-panel{min-height:275px}.world-map{height:151px}.lower-grid{margin-top:12px}.left-column{gap:12px}.panel-head{padding:18px 18px 13px}.civilizations{padding:0 18px 11px}.civ-row{grid-template-columns:minmax(110px,1.1fr) .68fr .72fr .72fr;gap:6px;padding:12px 0}.civ-name{font-size:10px}.civ-stat strong{font-size:10px}.civ-stat .small-label{font-size:6px}.focus-chip{font-size:7px;padding:4px}.chronicle{padding:0 18px 12px}.action-intro{margin-left:18px;margin-right:18px}.action-list{padding:0 18px}.custom-form{margin-left:18px;margin-right:18px}.turn-foot{padding-left:18px;padding-right:18px}.metric-row{margin-left:18px;margin-right:18px}.era-block{padding-left:18px;padding-right:18px}.divine-favor{margin-left:18px;margin-right:18px}.world-map{margin-left:17px;margin-right:17px}.map-footer{margin:0 17px}footer{height:52px;font-size:7px}}
@media(max-width:390px){.civ-row{grid-template-columns:minmax(97px,1fr) .61fr .65fr .66fr;gap:5px}.civ-emblem{width:25px;height:25px}.civ-identity{gap:7px}.civ-name{font-size:9px}.civ-sub{font-size:7px}.civ-stat .small-label{letter-spacing:.4px}.focus-chip{padding:3px 4px}.coordinates{font-size:7px}.metric{padding-left:8px}.metric strong{font-size:20px}}

(() => {
  'use strict';
  const SAVE_KEY = 'godsim-world-v1';
  const ERAS = ['Stone Age','Bronze Age','Iron Age','Classical Age','Medieval Age','Renaissance','Industrial Age','Atomic Age','Digital Age','Space Age','Interstellar Age','Galactic Age','Cosmic Age'];
  const TECH = {
    'Stone Age':['Gathering','Flint tools','Controlled fire','Storytelling'], 'Bronze Age':['Copper working','Bronze casting','Irrigation','Writing'], 'Iron Age':['Ironworking','Roads','Coinage','Siegecraft'], 'Classical Age':['Democracy','Aqueducts','Astronomy','Philosophy'], 'Medieval Age':['Steel forging','Sailing','Universities','Gunpowder'], 'Renaissance':['Printing press','Perspective','Navigation','Scientific method'], 'Industrial Age':['Steam power','Electricity','Railways','Vaccination'], 'Atomic Age':['Nuclear fission','Jet flight','Computing','Satellites'], 'Digital Age':['Microchips','The internet','Genetic science','Machine learning'], 'Space Age':['Orbital flight','Moon colonies','Fusion drive','Terraforming'], 'Interstellar Age':['Warp theory','Stellar habitats','Quantum networks','First contact'], 'Galactic Age':['Dyson swarms','Galactic cartography','Nanofabrication','Sentient worlds'], 'Cosmic Age':['Vacuum engineering','Universe seeding','Causal architecture','Transcendence']
  };
  const ACTIONS = [
    {id:'seed',icon:'✧',name:'Seed a companion',desc:'Give the first human a chance at family and a future.',cost:0},
    {id:'inspire',icon:'⌁',name:'Whisper an idea',desc:'Nudge a culture toward a new discovery.',cost:12},
    {id:'bless',icon:'❋',name:'Bless the land',desc:'Bring abundance, growth, and grateful hearts.',cost:18},
    {id:'settle',icon:'⌖',name:'Open a frontier',desc:'Guide a people to found a distant settlement.',cost:28},
    {id:'peace',icon:'☼',name:'Preach harmony',desc:'Cool rivalries and encourage understanding.',cost:22},
    {id:'storm',icon:'ϟ',name:'Unleash a trial',desc:'A storm tests the people and tempers their resolve.',cost:10}
  ];
  const names = ['Aru','Veyra','Namar','Oruun','Talvi','Kesh','Ilyr','Sola','Miren','Aeth'];
  const surnames = ['Riverfolk','Ashen','Highland','Dawn','Cedar','Ember','Tideborn','Silver','Verdant','Starward'];
  const symbols = ['ᚨ','ᚾ','ᛉ','ᚱ','ᛟ','ᚦ','ᛃ','ᚠ','ᛞ','ᛋ'];
  const $ = id => document.getElementById(id);
  const rand = (min,max) => Math.floor(Math.random()*(max-min+1))+min;
  const pick = arr => arr[Math.floor(Math.random()*arr.length)];
  const escapeHtml = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  function freshWorld(){return {turn:1,year:0,era:0,progress:0,favor:100,civs:[{id:1,name:'Firstborn',pop:1,tech:'Gathering',focus:'Expansion',opinion:50,settlements:[{name:'First Hearth',x:37,y:53}]}],wars:[],chronicle:[{turn:1,year:0,text:'In a quiet valley, the first human opens their eyes beneath an unmarked sky.'},{turn:1,year:0,text:'No fire burns. No shelter stands. The world waits for its first divine command.'},{turn:1,year:0,text:'A whole future rests in the hands of one small, fragile life.'}],nextId:2,seeded:false,sound:false};}
  let state;
  try {const saved=JSON.parse(localStorage.getItem(SAVE_KEY));state=saved&&Array.isArray(saved.civs)?saved:freshWorld();}catch(_){state=freshWorld();}
  let toastTimer;
  const eraName=()=>state.era<ERAS.length?ERAS[state.era]:`${['','Transcendent ','Eternal ','Infinite '][Math.min(3,Math.floor((state.era-ERAS.length)/3)+1)]}${['Cosmic','Omniversal','Beyond'][Math.min(2,Math.floor((state.era-ERAS.length)/3))]} Age ${Math.max(1,state.era-ERAS.length+1)}`;
  const techName=(era=state.era)=> era<ERAS.length?(TECH[ERAS[era]]||TECH['Cosmic Age'])[Math.max(0,Math.min(3,state.progress%4))]:['Reality weaving','Consciousness lattices','Multiverse engines','Origin design'][state.progress%4];
  function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));}catch(_){} $('turn-label').textContent=`TURN ${String(state.turn).padStart(2,'0')}`;}
  function log(text){state.chronicle.unshift({turn:state.turn,year:state.year,text});state.chronicle=state.chronicle.slice(0,40);}
  function totalPop(){return state.civs.reduce((sum,c)=>sum+c.pop,0);}
  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500);}
  function render(){
    save();const pop=totalPop(),warCount=state.wars.length,settlements=state.civs.reduce((sum,c)=>sum+c.settlements.length,0);
    $('era-name').textContent=eraName();$('population').textContent=pop.toLocaleString();$('civ-count').textContent=state.civs.length;$('war-count').textContent=warCount;$('war-caption').textContent=warCount?`${warCount===1?'one conflict':'conflicts rage'}`:'peace reigns';$('settlement-count').textContent=settlements;$('world-age').textContent=`YEAR ${state.year.toLocaleString()}`;$('civ-title-count').textContent=String(state.civs.length).padStart(2,'0');$('chronicle-count').textContent=String(Math.min(state.chronicle.length,99)).padStart(2,'0');$('favor-value').textContent=state.favor;
    const threshold=state.era<ERAS.length?6:5,progress=Math.min(100,Math.round((state.progress%threshold)/threshold*100));$('era-progress').style.width=`${progress}%`;$('progress-pct').textContent=`${progress}%`;$('next-era').textContent=state.progress>=threshold?`A new age dawns`:`Next: ${state.era<ERAS.length-1?ERAS[state.era+1]:state.era===ERAS.length-1?'Cosmic Age':`${eraName()}+`}`;
    $('favor-copy').textContent=state.favor>65?'Your influence is strong. The world listens.':state.favor>30?'Your influence is waning. Choose your moments.':'Your power is faint. Let time restore it.';
    renderMap();renderCivs();renderChronicle();renderActions();
  }
  function renderMap(){const map=$('world-map');map.innerHTML='<span class="map-river"></span><span class="map-label" style="left:9%;top:23%">MISTWOOD</span><span class="map-label" style="left:61%;top:15%">THE OLD SEA</span><span class="map-label" style="left:67%;top:78%">SOUTHERN REACH</span>';let i=0;state.civs.forEach(c=>c.settlements.forEach(s=>{const el=document.createElement('span');el.className=`map-settlement${i?' new':''}`;el.style.left=`${s.x}%`;el.style.top=`${s.y}%`;el.innerHTML=`<i></i><small>${escapeHtml(s.name)}</small>`;map.appendChild(el);i++;}));}
  function renderCivs(){const root=$('civilizations');root.innerHTML='';state.civs.forEach((c,i)=>{const row=document.createElement('div');row.className='civ-row';const opinionClass=c.opinion<35?'angry':c.opinion<60?'neutral':'';const involved=state.wars.some(w=>w.a===c.id||w.b===c.id);row.innerHTML=`<div class="civ-identity"><span class="civ-emblem">${symbols[i%symbols.length]}</span><div><div class="civ-name">${escapeHtml(c.name)}</div><div class="civ-sub">${c.settlements.length} ${c.settlements.length===1?'settlement':'settlements'}</div></div></div><div class="civ-stat"><span class="small-label">POPULATION</span><strong>${c.pop.toLocaleString()}</strong></div><div class="civ-stat"><span class="small-label">KEY TECH</span><strong>${escapeHtml(c.tech)}</strong></div><div class="civ-stat"><span class="small-label">FOCUS · OPINION</span><strong><span class="focus-chip ${involved?'war':''}">${involved?'War':escapeHtml(c.focus)}</span> <span class="opinion"><i class="opinion-dot ${opinionClass}"></i>${c.opinion}</span></strong></div>`;root.appendChild(row);});}
  function renderChronicle(){const root=$('chronicle');root.innerHTML=state.chronicle.slice(0,9).map(e=>`<div class="event"><span class="event-time">Y${e.year}</span><i class="event-mark"></i><div class="event-copy">${escapeHtml(e.text)}</div></div>`).join('');}
  function renderActions(){const root=$('actions');root.innerHTML='';let opts;if(state.civs.length===1&&state.civs[0].pop===1&&!state.seeded)opts=[ACTIONS[0],ACTIONS[1],ACTIONS[2]];else if(state.wars.length)opts=[ACTIONS[3],ACTIONS[4],ACTIONS[2]];else opts=[ACTIONS[1],ACTIONS[3],ACTIONS[2]];opts.forEach(a=>{const b=document.createElement('button');b.type='button';b.className='action-card';b.disabled=a.cost>state.favor;b.innerHTML=`<span class="action-icon">${a.icon}</span><span class="action-copy"><strong>${a.name}</strong><small>${a.desc}</small></span><span class="action-cost">${a.cost?`<span>✧</span> ${a.cost}`:'FREE'}</span>`;b.addEventListener('click',()=>takeTurn(a.id));root.appendChild(b);});}
  function newCiv(){const idx=(state.nextId-2)%names.length;const n=state.nextId++;const x=18+((n*29)%70),y=23+((n*37)%57);return {id:n,name:`${names[idx]} ${surnames[idx]}`,pop:Math.max(4,Math.floor(totalPop()*.16)),tech:pick(TECH[eraName()]||TECH['Cosmic Age']),focus:pick(['Expansion','Tech','War']),opinion:rand(38,76),settlements:[{name:pick(['New Hearth','Stonebridge','Greenbank','Farhaven','Sunreach','Hollowmere']),x,y}]};}
  function growWorld(){let events=[];let elapsed=state.era<2?20:state.era<5?35:state.era<9?60:120;state.year+=elapsed;
    // Population grows with the world's accumulated knowledge; the initial pair has a gentle chance to begin a family.
    state.civs.forEach(c=>{if(c.pop===1){if(state.seeded&&Math.random()<.78){c.pop=2;events.push(`${c.name} finds companionship; two lives now share the valley.`);}return;}const rate=state.era<4?.13:state.era<8?.09:.055;const born=Math.max(0,Math.floor(c.pop*rate)+ (Math.random()<.65?1:0));if(born){c.pop+=born;if(Math.random()<.42)events.push(`${c.name} welcomes ${born} ${born===1?'new soul':'new souls'} into its growing community.`);}});
    // Civilization expands into distinct cultures as population and settlement pressure mount.
    for(const c of [...state.civs]){if(state.civs.length<7&&c.pop>=28&&c.settlements.length<3&&Math.random()<.24){const child=newCiv();c.pop-=child.pop;state.civs.push(child);events.push(`${child.name} emerges from ${c.name}, carrying its own customs toward a new frontier.`);break;}if(c.pop>=18&&c.settlements.length<3&&Math.random()<.14){const s={name:pick(['Farhaven','New Hearth','Rivergate','Stonewatch','Dawnstead']),x:14+rand(0,72),y:18+rand(0,65)};c.settlements.push(s);events.push(`${c.name} founds ${s.name}, reaching beyond its ancestral home.`);}}
    // Independent discovery, accelerated by divine inspiration.
    if(Math.random()<.42+Math.min(.3,state.era*.025)){state.progress++;state.civs.forEach(c=>{if(Math.random()<.55)c.tech=techName();});if(Math.random()<.66)events.push(`An unexpected insight spreads: ${pick(TECH[eraName()]||TECH['Cosmic Age'])} changes what the people believe possible.`);}
    const threshold=state.era<ERAS.length?6:5;if(state.progress>=threshold){state.progress-=threshold;state.era++;state.civs.forEach(c=>{c.tech=techName();});events.push(`A new age begins. The world enters the ${eraName()}, and yesterday's miracles become ordinary.`);}
    // Wars arise from rivalry, and tend to resolve over a few turns.
    if(!state.wars.length&&state.civs.length>1&&Math.random()<.14+Math.max(0,(55-state.civs.reduce((s,c)=>s+c.opinion,0)/state.civs.length)/250)){const [a,b]=state.civs.slice().sort(()=>Math.random()-.5).slice(0,2);state.wars.push({a:a.id,b:b.id,turns:0});a.opinion=Math.max(5,a.opinion-12);b.opinion=Math.max(5,b.opinion-12);a.focus='War';b.focus='War';events.push(`A border dispute ignites between ${a.name} and ${b.name}. The first war begins.`);}
    state.wars=state.wars.filter(w=>{w.turns++;const a=state.civs.find(c=>c.id===w.a),b=state.civs.find(c=>c.id===w.b);if(!a||!b)return false;const lossA=Math.min(a.pop-1,rand(0,Math.max(1,Math.floor(a.pop*.04)))),lossB=Math.min(b.pop-1,rand(0,Math.max(1,Math.floor(b.pop*.04))));a.pop-=lossA;b.pop-=lossB;if(w.turns>=2||Math.random()<.19){const victor=a.pop>=b.pop?a:b,loser=victor===a?b:a;victor.opinion=Math.min(100,victor.opinion+8);loser.opinion=Math.max(5,loser.opinion-7);a.focus='Expansion';b.focus='Tech';events.push(`The fighting between ${a.name} and ${b.name} subsides. ${victor.name} claims the advantage, but both bear the cost.`);return false;}if(Math.random()<.48)events.push(`Skirmishes flare along the border; ${lossA+lossB} lives are lost in the conflict.`);return true;});
    state.civs.forEach(c=>{c.opinion=Math.max(5,Math.min(100,c.opinion+rand(-2,3)));if(Math.random()<.12)c.focus=pick(['Expansion','Tech','War']);});state.favor=Math.min(100,state.favor+rand(2,5));
    if(events.length<3)events.push(pick([`Seasons pass across the world; ${state.civs[0]?.name||'the people'} adapt to a changing landscape.`,`A quiet year brings new stories, customs, and small acts of ingenuity.`,`Wild herds cross the plains as settlements grow more sure of themselves.`,`The night sky turns overhead, indifferent to the plans of humankind.`]));
    return events;
  }
  function applyAction(id,custom){let extra=[];const target=state.civs[0];switch(id){case'seed':if(!state.seeded&&target.pop===1){state.seeded=true;extra.push('You place a kindred spirit in the first human’s path. The possibility of a family takes root.');}else{target.pop+=Math.max(2,Math.floor(target.pop*.12));extra.push('New lives arrive under your blessing, swelling the population.');}target.opinion=Math.min(100,target.opinion+10);break;
      case'inspire':state.progress+=2;state.civs.forEach(c=>{c.tech=techName();c.opinion=Math.min(100,c.opinion+4);});extra.push(`A dream of ${techName().toLowerCase()} visits the minds of curious mortals.`);break;
      case'bless':state.civs.forEach(c=>{const gain=Math.max(1,Math.floor(c.pop*.22));c.pop+=gain;c.opinion=Math.min(100,c.opinion+12);});state.progress++;extra.push('Fields flourish, illness retreats, and every hearth gives thanks for plenty.');break;
      case'settle':{const c=state.civs.slice().sort((a,b)=>b.pop-a.pop)[0];if(state.civs.length<7&&c.pop>=14){const child=newCiv();c.pop-=child.pop;state.civs.push(child);extra.push(`${child.name} sets out from ${c.name} to build a new home beyond the frontier.`);}else if(c.settlements.length<5){c.settlements.push({name:pick(['New Hearth','Rivergate','Farhaven','Dawnstead']),x:15+rand(0,70),y:20+rand(0,60)});extra.push(`${c.name} establishes a settlement beyond its familiar borders.`);}else{state.progress+=2;extra.push('The frontier is mapped; new knowledge returns in place of new land.');}break;}
      case'peace':state.wars=[];state.civs.forEach(c=>{c.opinion=Math.min(100,c.opinion+22);if(c.focus==='War')c.focus='Expansion';});extra.push('A hush falls over the battlefields. Old rivals lower their weapons and remember common ground.');break;
      case'storm':{const c=pick(state.civs);const loss=Math.max(0,Math.floor(c.pop*.07));c.pop=Math.max(1,c.pop-loss);c.tech=techName();state.progress++;extra.push(`A fierce storm tests ${c.name}; from hardship, they learn ${c.tech.toLowerCase()}.`);break;}
      default: if(custom){const lower=custom.toLowerCase();if(/peace|truce|stop war|harmony/.test(lower))return applyAction('peace');if(/settle|frontier|explor|colony|expand/.test(lower))return applyAction('settle');if(/tech|idea|teach|invent|knowledge|discover/.test(lower))return applyAction('inspire');if(/bless|food|harvest|heal|health|rain/.test(lower))return applyAction('bless');if(/war|attack|fight|storm|curse/.test(lower))return applyAction('storm');if(/birth|family|life|people|human|companion/.test(lower))return applyAction('seed');state.progress++;state.favor=Math.max(0,state.favor-5);extra.push(`Your decree — “${custom}” — echoes through the world. The people search its meaning, and a new idea takes root.`);}break;}
    if(id!=='seed'&&id!=='custom')state.favor=Math.max(0,state.favor-(ACTIONS.find(a=>a.id===id)?.cost||0));return extra;}
  function takeTurn(id,custom=''){if(id!=='custom'){const action=ACTIONS.find(a=>a.id===id);if(action&&action.cost>state.favor){toast('Not enough divine influence. Let time restore your power.');return;}}const opening=applyAction(id,custom);state.turn++;const events=[...opening,...growWorld()];events.slice(0,3).reverse().forEach(log);if(!events.length)log('The world turns quietly beneath your watchful gaze.');render();$('custom-command').value='';$('chronicle').scrollTop=0;toast(`Turn ${state.turn-1} complete · ${eraName()}`);}
  $('custom-form').addEventListener('submit',e=>{e.preventDefault();const text=$('custom-command').value.trim();if(!text){$('custom-command').focus();return;}takeTurn('custom',text);});
  $('reset-button').addEventListener('click',()=>$('reset-modal').hidden=false);$('cancel-reset').addEventListener('click',()=>$('reset-modal').hidden=true);$('confirm-reset').addEventListener('click',()=>{state=freshWorld();$('reset-modal').hidden=true;render();toast('A new world opens its eyes.');});$('reset-modal').addEventListener('click',e=>{if(e.target===$('reset-modal'))$('reset-modal').hidden=true;});
  $('sound-toggle').addEventListener('click',e=>{state.sound=!state.sound;e.currentTarget.textContent=state.sound?'◗':'◖';toast(state.sound?'Sound enabled':'Sound muted');});
  render();
})();

